mapper.select:
SELECT lease.*, v.material_id
FROM evidence_read_lease lease
JOIN material_version v ON v.id = lease.version_id
WHERE lease.owner_key = #{ownerKey} AND lease.run_id = #{runId}
  AND lease.version_id = #{versionId} AND lease.revision_id = #{revisionId}
FOR UPDATE

SELECT lease.*, v.material_id
FROM evidence_read_lease lease
JOIN material_version v ON v.id = lease.version_id
JOIN material m ON m.id = v.material_id
WHERE lease.id = #{leaseId} AND lease.run_id = #{runId}
  AND lease.owner_key = #{ownerKey}
  AND m.owner_type = #{ownerType} AND m.owner_key = #{ownerKey}

mapper.update:
UPDATE evidence_read_lease
SET status = #{status}, expires_at = #{expiresAt}
WHERE id = #{leaseId} AND owner_key = #{ownerKey}
  AND status = #{expectedStatus} AND expires_at > UTC_TIMESTAMP(3)

UPDATE evidence_read_lease
SET status = 'EXPIRED'
WHERE status = 'ACTIVE' AND expires_at <= #{now}
ORDER BY expires_at LIMIT #{limit}
